// why: un tap du curateur pilote tout : pick -> upscale -> compose -> printful ; regen -> nouvelle génération
const cb = $input.first().json.body.callback_query;
if (!cb) return [];
const [action, id] = cb.data.split(':');
const tg = `https://api.telegram.org/bot${$vars.TG_TOKEN}`;
const sbh = { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'application/json' };
if (action === 'regen') {
  await this.helpers.httpRequest({ method: 'POST', url: `${$vars.N8N_BASE_URL}/webhook/streetwear-generate`, json: true, body: { cloth_id: id } });
  await this.helpers.httpRequest({ method: 'POST', url: `${tg}/answerCallbackQuery`, json: true, body: { callback_query_id: cb.id, text: 'regenerating\u2026' } });
  return [];
}
// pick
const concept = (await this.helpers.httpRequest({ method: 'GET', url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/cloth_concepts?id=eq.${id}&select=*`, headers: sbh, json: true }))[0];
await this.helpers.httpRequest({ method: 'PATCH', url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/cloth_concepts?id=eq.${id}`, headers: sbh, json: true, body: { selected: true } });
// upscale via replicate real-esrgan x4
const pred = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.replicate.com/v1/predictions', json: true,
  headers: { Authorization: `Bearer ${$vars.REPLICATE_KEY}`, 'Content-Type': 'application/json', Prefer: 'wait=60' },
  body: { version: $vars.REPLICATE_ESRGAN_VERSION, input: { image: concept.image_url, scale: 4 } } });
const upscaled = Array.isArray(pred.output) ? pred.output[0] : pred.output;
// compose : artwork + logo + totehm cloth name (edge function)
const composed = await this.helpers.httpRequest({ method: 'POST',
  url: 'https://abujjbkbbiumxrokozph.supabase.co/functions/v1/compose-artwork', json: true,
  headers: { Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'application/json' },
  body: { cloth_id: concept.cloth_id, source_url: upscaled } });
await this.helpers.httpRequest({ method: 'PATCH', url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${concept.cloth_id}`, headers: sbh, json: true,
  body: { status: 'approved', artwork_final_url: composed.final_url, artwork_print_url: composed.print_url } });
await this.helpers.httpRequest({ method: 'POST', url: `${$vars.N8N_BASE_URL}/webhook/streetwear-printful`, json: true, body: { cloth_id: concept.cloth_id } });
await this.helpers.httpRequest({ method: 'POST', url: `${tg}/answerCallbackQuery`, json: true, body: { callback_query_id: cb.id, text: '\u2713 encoded' } });
return [{ json: { ok: true } }];
